/**
 * Data access layer.
 *
 * JSON files are generated by scripts/build-data.mjs and served from /data.
 * Loading is lazy, de-duplicated, and resilient: if the network fails we try the
 * Cache API (populated by the service worker or by "Download for offline").
 */

import { roomOverrides } from "./store.js";

export const DATA_FILES = {
  meta: "meta.json",
  timetable: "timetable.json",
  students: "students.json",
  teachers: "teachers.json",
  rooms: "rooms.json",
  notices: "notices.json",
  papers: "papers.json",
  syllabus: "syllabus.json",
  campus: "campus.json",
  contacts: "contacts.json",
  knowledge: "knowledge.json",
  community: "community.json",
  sources: "sources.json",
  search: "search.json",
};

const memory = new Map();
const inflight = new Map();
const indexCache = new Map();

const OFFLINE_ASSETS = [
  "/",
  "/index.html",
  "/manifest.webmanifest",
  "/offline.html",
  "/assets/css/app.css",
  "/assets/js/app.js",
  "/assets/js/ui.js",
  "/assets/js/store.js",
  "/assets/js/data.js",
  "/assets/js/logic.js",
  "/assets/js/search.js",
  "/assets/js/assistant.js",
  "/assets/js/pages/today.js",
  "/assets/js/pages/timetable.js",
  "/assets/js/pages/people.js",
  "/assets/js/pages/rasta.js",
  "/assets/js/pages/study.js",
  "/assets/js/pages/community.js",
  "/assets/js/pages/notices.js",
  "/assets/js/pages/exams.js",
  "/assets/js/pages/assistant-page.js",
  "/assets/js/pages/settings.js",
  "/assets/js/pages/admin.js",
  "/assets/js/pages/about.js",
  "/assets/js/pages/more.js",
  "/assets/img/main-gate.jpg",
  "/assets/img/admin.jpg",
  "/assets/img/library.jpg",
  "/assets/img/lab.jpg",
  "/assets/img/auditorium.jpg",
  "/assets/img/workshop.jpg",
  "/assets/img/campus-life.jpg",
  "/assets/img/sports.jpg",
  "/assets/img/new-gate.jpg",
  "/assets/img/convocation.jpg",
  "/assets/img/admissions.jpg",
  "/assets/img/og.jpg",
  "/assets/icons/icon-192.png",
  "/assets/icons/icon-512.png",
];

async function readFromCaches(path) {
  if (!("caches" in window)) return null;
  try {
    const names = await caches.keys();
    for (const name of names) {
      const cache = await caches.open(name);
      const hit = await cache.match(path);
      if (hit) return hit;
    }
  } catch {
    /* ignore */
  }
  return null;
}

export async function load(name, { force = false } = {}) {
  const file = DATA_FILES[name];
  if (!file) throw new Error(`Unknown data file: ${name}`);
  if (!force && memory.has(name)) return memory.get(name);
  if (!force && inflight.has(name)) return inflight.get(name);

  const path = `/data/${file}`;
  const promise = (async () => {
    let response = null;
    try {
      response = await fetch(path, { cache: force ? "reload" : "default" });
      if (!response.ok) throw new Error(`HTTP ${response.status} for ${path}`);
    } catch (err) {
      const cached = await readFromCaches(path);
      if (!cached) throw err;
      response = cached;
    }
    const value = await response.json();
    memory.set(name, value);
    return value;
  })();

  inflight.set(name, promise);
  try {
    return await promise;
  } finally {
    inflight.delete(name);
  }
}

export function cached(name) {
  return memory.get(name) || null;
}

export async function loadMany(names) {
  const list = await Promise.all(names.map((name) => load(name).catch((err) => ({ __error: err }))));
  return Object.fromEntries(names.map((name, i) => [name, list[i]]));
}

/**
 * Flatten the envelope shapes used by the generated JSON into the shapes the
 * assistant and a few pages expect. Keeping this in one place prevents the
 * "people is not iterable" class of bug.
 */
export function assistantData(data = {}) {
  return {
    timetable: data.timetable || { sections: [], subgroups: [] },
    teachers: data.teachers?.teachers || (Array.isArray(data.teachers) ? data.teachers : []),
    students: data.students?.students || (Array.isArray(data.students) ? data.students : []),
    papers: data.papers?.papers || (Array.isArray(data.papers) ? data.papers : []),
    syllabus: data.syllabus || {},
    notices: data.notices || {},
    campus: data.campus || {},
    contacts: data.contacts || {},
    knowledge: data.knowledge || {},
    rooms: data.rooms || { rooms: [] },
    community: data.community || {},
  };
}

export function roomListOf(rooms) {
  if (Array.isArray(rooms)) return rooms;
  return rooms?.rooms || [];
}

/* ------------------------------------------------------------------ */
/* Timetable indexes                                                   */
/* ------------------------------------------------------------------ */

function buildIndex(key, factory) {
  if (indexCache.has(key)) return indexCache.get(key);
  const value = factory();
  indexCache.set(key, value);
  return value;
}

export function timetableIndex(timetable) {
  return buildIndex("timetable", () => {
    const sections = new Map();
    const subgroups = new Map();
    const byYear = new Map();
    for (const section of timetable.sections || []) {
      sections.set(section.id, section);
      if (!byYear.has(section.year)) byYear.set(section.year, []);
      byYear.get(section.year).push(section);
    }
    for (const group of timetable.subgroups || []) subgroups.set(group.id, group);
    return { sections, subgroups, byYear };
  });
}

export function getSection(timetable, id) {
  if (!timetable || !id) return null;
  return timetableIndex(timetable).sections.get(String(id).toUpperCase()) || null;
}

export function getSubgroup(timetable, id) {
  if (!timetable || !id) return null;
  return timetableIndex(timetable).subgroups.get(String(id).toUpperCase()) || null;
}

export function subgroupsFor(timetable, sectionId) {
  if (!timetable) return [];
  const prefix = String(sectionId || "").toUpperCase();
  return (timetable.subgroups || []).filter((g) => g.id.startsWith(prefix) && g.id !== prefix);
}

export function sectionsForYear(timetable, year) {
  if (!timetable) return [];
  return timetableIndex(timetable).byYear.get(Number(year)) || [];
}

export function sectionLabel(section) {
  if (!section) return "";
  return section.label || `${section.year} · ${section.branch} · ${section.group}`;
}

export function activeLecturesFor(section, { day = null, subgroup = "" } = {}) {
  if (!section) return [];
  const sub = String(subgroup || "").toUpperCase();
  return (section.lectures || [])
    .filter((lecture) => {
      if (day != null && lecture.day !== day) return false;
      if (!sub) return true;
      return !lecture.subsection || lecture.subsection === sub;
    })
    .sort((a, b) => a.day - b.day || a.period - b.period || String(a.subsection || "").localeCompare(String(b.subsection || "")));
}

/* ------------------------------------------------------------------ */
/* Teachers                                                            */
/* ------------------------------------------------------------------ */

const TITLES = /\b(dr|er|ms|mrs|mr|prof|sh|smt|shri|smt\.|capt|col|lt)\b\.?/gi;

export function normName(name = "") {
  return String(name)
    .toLowerCase()
    .replace(/\([^)]*\)/g, " ")
    .replace(TITLES, " ")
    .replace(/[^a-z ]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function teacherIndex(teachers) {
  return buildIndex("teachers", () => {
    const byKey = new Map();
    const byId = new Map();
    for (const teacher of teachers || []) {
      byId.set(teacher.id, teacher);
      const key = normName(teacher.name);
      if (!key) continue;
      if (!byKey.has(key)) byKey.set(key, []);
      byKey.get(key).push(teacher);
      const raw = normName(teacher.rawName || "");
      if (raw && raw !== key) {
        if (!byKey.has(raw)) byKey.set(raw, []);
        byKey.get(raw).push(teacher);
      }
    }
    return { byKey, byId };
  });
}

export function findTeacher(teachers, name) {
  if (!teachers || !name) return null;
  const { byKey } = teacherIndex(teachers);
  const key = normName(name);
  if (!key) return null;
  const exact = byKey.get(key);
  if (exact && exact.length) return exact[0];

  const parts = key.split(" ").filter(Boolean);
  if (parts.length >= 2) {
    const surname = parts[parts.length - 1];
    const first = parts[0][0];
    const candidates = [];
    for (const [candidateKey, list] of byKey) {
      const bits = candidateKey.split(" ").filter(Boolean);
      if (bits[bits.length - 1] === surname && bits[0][0] === first) candidates.push(...list);
    }
    const unique = [...new Map(candidates.map((c) => [c.id, c])).values()];
    if (unique.length === 1) return unique[0];
  }

  // last-name-only search, useful for "Kaur" style queries
  if (parts.length === 1) {
    const loose = [];
    for (const [candidateKey, list] of byKey) {
      if (candidateKey.includes(key)) loose.push(...list);
    }
    const unique = [...new Map(loose.map((c) => [c.id, c])).values()];
    if (unique.length === 1) return unique[0];
  }
  return null;
}

export function teachersMatching(teachers, query) {
  const q = normName(query);
  if (!q) return teachers || [];
  return (teachers || [])
    .map((teacher) => {
      const hay = normName(`${teacher.name} ${teacher.department} ${(teacher.subjects || []).join(" ")}`);
      let score = 0;
      if (normName(teacher.name).startsWith(q)) score += 100;
      if (normName(teacher.name).includes(q)) score += 60;
      if (hay.includes(q)) score += 25;
      const tokens = q.split(" ").filter(Boolean);
      for (const token of tokens) if (hay.includes(token)) score += 6;
      return { teacher, score };
    })
    .filter((row) => row.score > 0)
    .sort((a, b) => b.score - a.score || a.teacher.name.localeCompare(b.teacher.name))
    .map((row) => row.teacher);
}

/* ------------------------------------------------------------------ */
/* Students                                                            */
/* ------------------------------------------------------------------ */

export function studentIndex(students) {
  return buildIndex("students", () => {
    const byCrn = new Map();
    const byReg = new Map();
    for (const student of students || []) {
      if (student.crn) byCrn.set(String(student.crn), student);
      if (student.registrationNo) byReg.set(String(student.registrationNo), student);
    }
    return { byCrn, byReg };
  });
}

export function findStudent(students, query) {
  if (!students || !query) return null;
  const q = String(query).trim().toLowerCase();
  const { byCrn, byReg } = studentIndex(students);
  if (byCrn.has(q)) return byCrn.get(q);
  if (byReg.has(q)) return byReg.get(q);
  const exact = (students || []).find((s) => s.name.toLowerCase() === q);
  return exact || null;
}

export function studentsMatching(students, query) {
  const q = String(query || "").trim().toLowerCase();
  if (!q) return students || [];
  const tokens = q.split(/\s+/).filter(Boolean);
  return (students || [])
    .map((student) => {
      const hay = `${student.name} ${student.crn} ${student.registrationNo} ${student.section} ${student.batch}`.toLowerCase();
      if (!tokens.every((token) => hay.includes(token))) return null;
      let score = 0;
      if (String(student.crn) === q || String(student.registrationNo) === q) score += 200;
      if (student.name.toLowerCase().startsWith(q)) score += 90;
      if (student.name.toLowerCase().includes(q)) score += 50;
      return { student, score };
    })
    .filter(Boolean)
    .sort((a, b) => b.score - a.score || a.student.name.localeCompare(b.student.name))
    .map((row) => row.student);
}

/* ------------------------------------------------------------------ */
/* Rooms & places                                                      */
/* ------------------------------------------------------------------ */

const ROOM_ALIASES = [
  [/\bA ?9\b|AUTOMOBILE/i, "automobile-block"],
  [/\bA ?6\b/i, "automobile-block"],
  [/WORKSHOP|SMITHY|FOUNDRY|CARPENTRY|MACHINE SHOP|WELDING/i, "workshops"],
  [/^F\d/i, "f-block"],
  [/^S\d/i, "s-block"],
  [/^G\d/i, "g-block"],
  [/PHY|CHEM|ENG LAB|PHYSICS|CHEMISTRY/i, "applied-science"],
  [/CGL|CAD|ME DEPT|MECHANICAL/i, "me-dept"],
  [/BEE|ELECTRICAL|^EE/i, "ee-dept"],
  [/COMM|EC LAB|ELECTRONIC/i, "ec-dept"],
  [/^IT|INFORMATION TECH/i, "it-dept"],
  [/^CS|COMPUTER SCI/i, "cse-dept"],
  [/LIBRARY/i, "library"],
  [/AUDITORIUM/i, "auditorium"],
  [/SPORTS|GYM/i, "sports-complex"],
  [/CANTEEN|MESS/i, "canteen"],
];

export function normalizeRoom(room = "") {
  return String(room)
    .toUpperCase()
    .replace(/\([^)]*\)/g, " ")
    .replace(/[._/]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

export function roomIndex(rooms) {
  return buildIndex("rooms", () => {
    const byName = new Map();
    const byId = new Map();
    for (const room of rooms || []) {
      byId.set(room.id, room);
      const key = normalizeRoom(room.name);
      byName.set(key, room);
      byName.set(normalizeRoom(room.id.replace(/-/g, " ")), room);
    }
    return { byName, byId };
  });
}

export function findRoom(rooms, name) {
  if (!rooms || !name) return null;
  const { byName } = roomIndex(rooms);
  const key = normalizeRoom(name);
  if (byName.has(key)) return byName.get(key);
  // "F 107" → "F107"
  const compact = key.replace(/\s+/g, "");
  for (const [candidate, room] of byName) {
    if (candidate.replace(/\s+/g, "") === compact) return room;
  }
  return null;
}

export function inferPlaceForRoom(roomName) {
  const key = String(roomName || "").toUpperCase();
  for (const [pattern, place] of ROOM_ALIASES) if (pattern.test(key)) return place;
  return "";
}

export function placeForRoom(rooms, roomName) {
  if (!roomName) return "";
  const overrides = roomOverrides();
  const exact = overrides[roomName] || overrides[normalizeRoom(roomName)];
  if (exact) return exact;
  const room = findRoom(rooms, roomName);
  if (room?.place) return room.place;
  return inferPlaceForRoom(roomName);
}

export function placeIndex(campus) {
  return buildIndex("places", () => {
    const byId = new Map();
    for (const place of campus?.places || []) byId.set(place.id, place);
    return { byId };
  });
}

export function getPlace(campus, id) {
  if (!campus || !id) return null;
  return placeIndex(campus).byId.get(id) || null;
}

export function findPlaces(campus, query) {
  const q = String(query || "").trim().toLowerCase();
  if (!campus) return [];
  if (!q) return campus.places || [];
  const tokens = q.split(/\s+/).filter(Boolean);
  return (campus.places || [])
    .map((place) => {
      const hay = `${place.name} ${place.id} ${(place.aliases || []).join(" ")} ${place.description || ""} ${place.category}`.toLowerCase();
      if (!tokens.every((token) => hay.includes(token))) return null;
      let score = 0;
      if (place.name.toLowerCase().startsWith(q)) score += 100;
      if (place.name.toLowerCase().includes(q)) score += 50;
      if ((place.aliases || []).some((a) => a.toLowerCase() === q)) score += 120;
      return { place, score };
    })
    .filter(Boolean)
    .sort((a, b) => b.score - a.score || a.place.name.localeCompare(b.place.name))
    .map((row) => row.place);
}

/* ------------------------------------------------------------------ */
/* Papers & syllabus                                                   */
/* ------------------------------------------------------------------ */

export function paperSearch(papers, query, { session = "", department = "" } = {}) {
  const q = String(query || "").trim().toLowerCase();
  const tokens = q.split(/\s+/).filter(Boolean);
  return (papers || [])
    .filter((paper) => {
      if (session && paper.session !== session) return false;
      if (department && paper.department !== department) return false;
      if (!tokens.length) return true;
      const hay = `${paper.code} ${paper.title} ${paper.name} ${paper.department} ${paper.session}`.toLowerCase();
      return tokens.every((token) => hay.includes(token));
    })
    .map((paper) => {
      const code = String(paper.code || "").toLowerCase();
      let score = 0;
      if (code && code === q) score += 200;
      if (code && code.startsWith(q)) score += 120;
      if (code && code.includes(q)) score += 60;
      if (String(paper.title || "").toLowerCase().includes(q)) score += 30;
      score += Number(paper.year || 0) / 1000;
      return { paper, score };
    })
    .sort((a, b) => b.score - a.score || String(b.paper.year).localeCompare(String(a.paper.year)))
    .map((row) => row.paper);
}

export function syllabusSearch(documents, query, { program = "", code = "" } = {}) {
  const q = String(query || "").trim().toLowerCase();
  const tokens = q.split(/\s+/).filter(Boolean);
  return (documents || [])
    .filter((doc) => {
      if (program && doc.program !== program) return false;
      if (code && doc.branch !== code && doc.code !== code) return false;
      if (!tokens.length) return true;
      const hay = `${doc.title} ${doc.branch} ${doc.branchName} ${doc.program} ${doc.semester} ${doc.scheme}`.toLowerCase();
      return tokens.every((token) => hay.includes(token));
    })
    .sort((a, b) => String(b.scheme).localeCompare(String(a.scheme)) || a.title.localeCompare(b.title));
}

/* ------------------------------------------------------------------ */
/* Notices                                                             */
/* ------------------------------------------------------------------ */

export function upcomingHolidays(holidays, from = new Date()) {
  const start = new Date(from.getFullYear(), from.getMonth(), from.getDate()).getTime();
  return (holidays || [])
    .filter((holiday) => {
      const [y, m, d] = String(holiday.date).split("-").map(Number);
      return new Date(y, m - 1, d).getTime() >= start;
    })
    .sort((a, b) => String(a.date).localeCompare(String(b.date)));
}

export function noticeSearch(notices, query, kind = "") {
  const q = String(query || "").trim().toLowerCase();
  const tokens = q.split(/\s+/).filter(Boolean);
  return (notices || [])
    .filter((notice) => {
      if (kind && notice.kind !== kind) return false;
      if (!tokens.length) return true;
      const hay = `${notice.title} ${notice.summary || ""} ${notice.source} ${notice.kind}`.toLowerCase();
      return tokens.every((token) => hay.includes(token));
    })
    .sort((a, b) => String(b.date).localeCompare(String(a.date)));
}

/* ------------------------------------------------------------------ */
/* Offline prefetch                                                    */
/* ------------------------------------------------------------------ */

export async function prefetchAll(onProgress = () => {}) {
  if (!("caches" in window)) throw new Error("This browser does not support offline storage.");
  const cache = await caches.open("gndec-one-v1");
  const urls = [
    ...Object.values(DATA_FILES).map((file) => `/data/${file}`),
    ...OFFLINE_ASSETS,
    "/assets/js/pages/more.js",
  ];
  const unique = [...new Set(urls)];
  let done = 0;
  const failures = [];
  for (const url of unique) {
    try {
      const response = await fetch(url, { cache: "reload" });
      if (response.ok) await cache.put(url, response.clone());
      else failures.push({ url, status: response.status });
    } catch (err) {
      failures.push({ url, error: String(err) });
    }
    done += 1;
    onProgress(done, unique.length);
  }
  return { total: unique.length, cached: unique.length - failures.length, failures };
}

export async function clearDataCaches() {
  memory.clear();
  indexCache.clear();
  if (!("caches" in window)) return;
  const names = await caches.keys();
  await Promise.all(names.filter((name) => name.startsWith("gndec-one")).map((name) => caches.delete(name)));
}

export async function storageEstimate() {
  if (!navigator.storage?.estimate) return null;
  const { usage = 0, quota = 0 } = await navigator.storage.estimate();
  return { usage, quota, percent: quota ? Math.round((usage / quota) * 100) : 0 };
}

export function prettyBytes(bytes) {
  if (!bytes) return "0 KB";
  const units = ["B", "KB", "MB", "GB"];
  const i = Math.min(Math.floor(Math.log(bytes) / Math.log(1024)), units.length - 1);
  return `${(bytes / 1024 ** i).toFixed(i === 0 ? 0 : 1)} ${units[i]}`;
}
